<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\Accessor\ThemeVersionContentTextAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ThemeVersionContentTextAccessor trait.
 *
 * Covers null default, string/VO assignment via withContentText,
 * getContentText/contentText accessors, and isContentTextChanged with/without original.
 */
class ThemeVersionContentTextAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withContentText creates a new instance with the ContentText set
     * from a string value, and getContentText returns the primitive string.
     */
    public function testWithContentTextFromString(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionContentTextAccessorUnitTest();

        // Act
        $result = $holder->withContentText('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getContentText());
    }
    /**
     * Asserts that withcontentText has access to the value object
     * from a string value, and getContentText returns the primitive string.
     */
    public function testWithContentTextFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionContentTextAccessorUnitTest();

        // Act
        $result = $holder->withContentText('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->contentText()->value());
    }
    public function testChangedContentText(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionContentTextAccessorUnitTest();
        $original = $holder->withContentText('one');
        $same = $holder->withContentText('one');
        $modified = $holder->withContentText('other');

        // Act
        $unchanged = $holder->isContentTextChanged();
        $withSame = $original->isContentTextChanged($same);
        $withDiferent = $original->isContentTextChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithThemeVersionContentTextAccessorUnitTest
{
    use ThemeVersionContentTextAccessor;
}
